package dev.slithergoh.pixelmonradar.client.screen;

import dev.slithergoh.pixelmonradar.client.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.Screen;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.block.Block;import java.util.*;
public final class OreScreen extends Screen{private EditBox search;private List<ResourceLocation>ores=List.of();private int scroll;public OreScreen(){super(Component.literal("Ore Scanner"));}@Override protected void init(){int l=width/2-230;ores=OreScanner.candidates();search=new EditBox(font,l+12,45,250,22,Component.literal("Search blocks"));search.setHint(Component.literal("Search ores / Pixelmon blocks..."));addRenderableWidget(search);addRenderableWidget(Button.builder(Component.literal("Highlights: "+on(RadarSettings.oreEspEnabled)),b->{RadarSettings.oreEspEnabled=!RadarSettings.oreEspEnabled;b.setMessage(Component.literal("Highlights: "+on(RadarSettings.oreEspEnabled)));RadarSettings.save();}).bounds(l+270,45,115,22).build());addRenderableWidget(Button.builder(Component.literal("Range "+RadarSettings.oreRange+"m"),b->{RadarSettings.oreRange=RadarSettings.oreRange>=64?8:RadarSettings.oreRange+8;b.setMessage(Component.literal("Range "+RadarSettings.oreRange+"m"));RadarSettings.save();}).bounds(l+390,45,70,22).build());addRenderableWidget(Button.builder(Component.literal("Clear"),b->{RadarSettings.selectedOres.clear();RadarSettings.save();}).bounds(l+390,72,70,20).build());}private static String on(boolean v){return v?"ON":"OFF";}private List<ResourceLocation>f(){String q=search==null?"":search.getValue().toLowerCase();return ores.stream().filter(x->x.toString().toLowerCase().contains(q)).toList();}@Override public void render(GuiGraphics g,int mx,int my,float pt){renderBackground(g,mx,my,pt);int l=width/2-230,r=l+460;g.fill(l,18,r,height-18,0xE00D1720);g.fill(l,18,r,38,0xFF172A3A);g.drawString(font,"ORE SCANNER",l+12,25,0x8FE8FF,true);g.drawString(font,RadarSettings.selectedOres.size()+" selected",r-75,25,0xA8D8E8,false);super.render(g,mx,my,pt);List<ResourceLocation>a=f();int max=Math.max(1,(height-125)/38);scroll=Math.min(scroll,Math.max(0,a.size()-max));int y=101;Minecraft mc=Minecraft.getInstance();for(int i=scroll;i<a.size()&&i<scroll+max;i++){ResourceLocation id=a.get(i);boolean s=RadarSettings.selectedOres.contains(id.toString());g.fill(l+10,y-3,r-10,y+31,s?0xFF214C45:0xCC17212B);Block block=BuiltInRegistries.BLOCK.get(id);ItemStack stack=new ItemStack(block.asItem());if(!stack.isEmpty())g.renderItem(stack,l+17,y+5);String display=stack.isEmpty()?id.getPath():stack.getHoverName().getString();g.drawString(font,display,l+42,y+3,s?0xA9FFD4:0xFFFFFF,true);g.drawString(font,id.toString(),l+42,y+16,0x82909B,false);g.drawString(font,s?"SELECTED":"click to select",r-92,y+10,s?0x7CFFB2:0x84919A,false);y+=38;}g.drawString(font,"Mouse wheel to scroll  •  Click a block card to toggle",l+12,height-31,0x91A5B3,false);}@Override public boolean mouseClicked(double mx,double my,int b){int l=width/2-230;List<ResourceLocation>a=f();int max=Math.max(1,(height-125)/38),y=101;if(mx>=l+10&&mx<=l+450)for(int i=scroll;i<a.size()&&i<scroll+max;i++,y+=38)if(my>=y-3&&my<=y+31){String id=a.get(i).toString();if(!RadarSettings.selectedOres.remove(id))RadarSettings.selectedOres.add(id);RadarSettings.save();return true;}return super.mouseClicked(mx,my,b);}@Override public boolean mouseScrolled(double mx,double my,double sx,double sy){List<ResourceLocation>a=f();int max=Math.max(1,(height-125)/38);scroll=Math.max(0,Math.min(Math.max(0,a.size()-max),scroll+(sy<0?1:-1)));return true;}@Override public void onClose(){RadarSettings.save();super.onClose();}@Override public boolean isPauseScreen(){return false;}}
